import assert from "node:assert/strict";
import { it } from "node:test";
import { Volume } from "memfs";
import { createFfmpegCommand } from "./index.js";

// Native FFmpeg 7.0.2, 2x2 gbrapf32le, encoded with -c:v exr and the options below.
// G: -.25,.125,.5,1.5; B: .375,.25,2,.75; R: .75,1,-.5,.0625; A: .125,.25,.5,1.
const fixtures = {
  "float": "",
  "half": "",
  "zip16": ""
} as const;
const expected = Buffer.from("c0006020ff2040400080ff8010ffc0ff", "hex");

async function run(bytes: Uint8Array, inputArgs: string[]) {
  const volume = Volume.fromJSON({ "/in.exr": Buffer.from(bytes), "/frame0.exr": Buffer.from(bytes) });
  const stdout: Uint8Array[] = [];
  let stderr = "";
  const result = await createFfmpegCommand().execute({
    args: ["-v", "error", ...inputArgs, "-pix_fmt", "rgba", "-f", "rawvideo", "pipe:1"],
    cwd: "/", env: {}, signal: new AbortController().signal,
    fs: {
      async readFile(path: string) { return volume.readFileSync(path); },
      async stat(path: string) { return volume.statSync(path); }
    },
    stdin: (async function* () { yield bytes; })(),
    stdout: { async write(data: Uint8Array) { stdout.push(data); } },
    stderr: { async write(data: Uint8Array) { stderr += new TextDecoder().decode(data); } }
  } as never);
  return { ...result, stdout: Buffer.concat(stdout), stderr };
}

for (const [format, hex] of Object.entries(fixtures)) {
  for (const input of [
    ["-i", "/in.exr"],
    ["-i", "pipe:0"],
    ["-i", "/frame%d.exr"],
    ["-f", "image2", "-i", "/in.exr"],
    ["-f", "image2pipe", "-c:v", "exr", "-i", "/in.exr"],
    ["-f", "image2pipe", "-i", "pipe:0"]
  ]) {
    it(`decodes native ${format} EXR to exact RGBA: ${input.join(" ")}`, async () => {
      const result = await run(Buffer.from(hex, "hex"), input);
      assert.equal(result.exitCode, 0, result.stderr);
      assert.equal(result.stderr, "");
      assert.deepEqual(result.stdout, expected);
    });
  }
}

it("keeps concatenated float, half and ZIP16 EXR frames in order", async () => {
  const bytes = Buffer.concat(Object.values(fixtures).map(hex => Buffer.from(hex, "hex")));
  const result = await run(bytes, ["-f", "image2pipe", "-c:v", "exr", "-i", "pipe:0"]);
  assert.equal(result.exitCode, 0, result.stderr);
  assert.deepEqual(result.stdout, Buffer.concat([expected, expected, expected]));
});

for (const input of [["-i", "/in.exr"], ["-f", "image2pipe", "-c:v", "exr", "-i", "/in.exr"]]) {
  it(`rejects truncated EXR without placeholder pixels: ${input.join(" ")}`, async () => {
    const result = await run(Buffer.from(fixtures.zip16, "hex").subarray(0, -1), input);
    assert.notEqual(result.exitCode, 0);
    assert.equal(result.stdout.length, 0);
  });
}

// Native FFmpeg 7.0.2: 3x17 gbrpf32le, sample[i] = (i*37%193)/128-.25, ZIP16.
it("decodes ZIP16 across scanline blocks and supplies opaque alpha for RGB", async () => {
  const bytes = Buffer.from("", "hex");
  const expected = Buffer.from("", "hex");
  for (const input of [["-i", "/in.exr"], ["-f", "image2pipe", "-c:v", "exr", "-i", "pipe:0"]]) {
    const result = await run(bytes, input);
    assert.equal(result.exitCode, 0, result.stderr);
    assert.deepEqual(result.stdout, expected);
  }
});

it("rejects an EXR filename with an invalid signature", async () => {
  const bytes = Buffer.from(fixtures.float, "hex");
  bytes[0] = 0;
  const result = await run(bytes, ["-i", "/in.exr"]);
  assert.notEqual(result.exitCode, 0);
  assert.equal(result.stdout.length, 0);
});
